results.js:
morse.watch("body > div.mn > div.row2 > div.tbl > h3", h => {
  if (h.parentNode.querySelector(".csv-export")) return;
  const btn = morse.el("button", {
    class: "csv-export",
    type: "button",
    text: "Export CSV",
    on: {
      click: () => {
        const table = morse.$("body > div.mn > div.row2 > div.tbl table");
        if (!table) return morse.toast("No orders table found");
        const esc = v => `"${String(v).replace(/"/g, '""')}"`;
        const rows = [...table.querySelectorAll("tr")].map(tr =>
          [...tr.children].map(c => esc(c.textContent.trim())).join(",")
        );
        const blob = new Blob([rows.join("\n")], { type: "text/csv" });
        const url = URL.createObjectURL(blob);
        const a = morse.el("a", { href: url, download: "orders.csv" });
        document.body.appendChild(a);
        a.click();
        a.remove();
        setTimeout(() => URL.revokeObjectURL(url), 1000);
        morse.toast("Exported " + (rows.length - 1) + " orders");
      }
    }
  });
  h.after(btn);
});

