morse.watch("body > div.mn > h1", h1 => {
  if (h1.dataset.csvAdded) return;
  h1.dataset.csvAdded = "1";
  h1.style.display = "flex";
  h1.style.alignItems = "center";
  h1.style.gap = "12px";
  const btn = morse.el("button", { id: "csv-export-btn", type: "button", text: "Export CSV", on: { click: exportCsv } });
  h1.appendChild(btn);
});

function exportCsv() {
  const rows = morse.$$("body > div.mn > div.row2 > div.tbl table tr");
  const lines = rows.map(tr =>
    Array.from(tr.children)
      .map(cell => '"' + cell.textContent.trim().replace(/"/g, '""') + '"')
      .join(",")
  );
  const csv = lines.join("\n");
  const url = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
  const a = morse.el("a", { href: url, download: "orders.csv" });
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  morse.toast("Exported " + Math.max(0, rows.length - 1) + " orders");
}

