results.js:
morse.watch("th.am", th => {
  morse.on(th, "click", () => {
    const tbody = th.closest("table").querySelector("tbody");
    if (!tbody) return;
    const asc = th.dataset.dir !== "asc";
    th.dataset.dir = asc ? "asc" : "desc";
    const val = r => parseFloat((r.querySelector("td.am")?.textContent || "").replace(/[^0-9.\-]/g, "")) || 0;
    const rows = [...tbody.querySelectorAll("tr")];
    rows.sort((a, b) => asc ? val(a) - val(b) : val(b) - val(a));
    rows.forEach(r => tbody.appendChild(r));
  });
});

morse.watch("div.tbl table", el => {
  const table = el;
  const head = table.querySelector("thead th.am");
  const body = table.querySelector("tbody");
  if (!head || !body || head.dataset.sortBound) return;
  head.dataset.sortBound = "1";
  head.style.cursor = "pointer";
  head.title = "Sort by amount";
  let asc = false;
  const amt = r => parseFloat(r.querySelector("td.am")?.textContent.replace(/[^0-9.\-]/g, "")) || 0;
  morse.on(head, "click", () => {
    asc = !asc;
    const rows = Array.from(body.querySelectorAll("tr"));
    rows.sort((a, b) => asc ? amt(a) - amt(b) : amt(b) - amt(a));
    rows.forEach(r => body.appendChild(r));
    head.textContent = "Amount " + (asc ? "▲" : "▼");
  });
});

