morse.watch("div.tbl table", function (table) {
  let sum = 0;
  table.querySelectorAll("tbody td.am").forEach(function (td) {
    const n = parseFloat(td.textContent);
    if (!isNaN(n)) sum += n;
  });
  const total = sum.toFixed(2);

  let foot = table.querySelector("tfoot");
  if (!foot) {
    foot = morse.el("tfoot");
    table.appendChild(foot);
  }
  let amountCell = foot.querySelector("td.am");
  if (!amountCell) {
    foot.appendChild(morse.el("tr", {},
      morse.el("td", { colspan: "4", text: "Total" }),
      morse.el("td", { class: "am", text: total })
    ));
    return;
  }
  // Only write when changed, so the observer doesn't loop.
  if (amountCell.textContent !== total) amountCell.textContent = total;
}, { live: true });

