results.js:
const steps = [0, 15, 30, 60];
let i = 0, timer = null;
morse.watch('[data-testid="player-controls"] .btns', (btns) => {
  const b = morse.el('button', { 'aria-label': 'Sleep timer', title: 'Sleep timer', text: 'Zz' });
  morse.on(b, 'click', () => {
    clearTimeout(timer);
    i = (i + 1) % steps.length;
    const m = steps[i];
    b.textContent = m ? m + 'm' : 'Zz';
    if (m) timer = setTimeout(() => {
      const pp = morse.$('button[data-testid="play-pause"]');
      if (pp && pp.getAttribute('aria-label') === 'Pause') pp.click();
      i = 0;
      b.textContent = 'Zz';
    }, m * 60000);
  });
  btns.append(b);
});

morse.watch('[data-testid="player-controls"] .btns', el => {
  if (el.querySelector('button.sleep')) return;
  let idx = 0, timer = null;
  const steps = [0, 15, 30, 45, 60];
  const btn = morse.el('button', {
    class: 'sleep',
    'aria-label': 'Sleep timer',
    title: 'Sleep timer: off',
    text: '☾',
    on: {
      click: () => {
        idx = (idx + 1) % steps.length;
        const mins = steps[idx];
        clearTimeout(timer);
        timer = null;
        if (mins === 0) {
          btn.textContent = '☾';
          btn.title = 'Sleep timer: off';
          morse.toast('Sleep timer off');
          return;
        }
        btn.textContent = mins + 'm';
        btn.title = 'Sleep timer: ' + mins + ' min';
        morse.toast('Playback stops in ' + mins + ' min');
        timer = setTimeout(() => {
          const pp = morse.$('button[data-testid="play-pause"]');
          if (pp && pp.getAttribute('aria-label') === 'Pause') pp.click();
          idx = 0;
          btn.textContent = '☾';
          btn.title = 'Sleep timer: off';
        }, mins * 60 * 1000);
      }
    }
  });
  el.append(btn);
});
